  if (price < 0) throw new RangeError("tax base");
  const base = Math.max(0, price - 10);
  const reduction = currency === "EUR" ? Math.min(rate, 0.15) : rate;
  const result = Math.round(base * (1 - reduction) * 100) / 100;
  return result * minorUnit;
}

